end

function UIBattlingPVPMgr:OnReceiveBattleEndPacketSuccessHandler_(packetId, data)
    if packetId == Constants.Packets.LadderMatchBattleEnd
    or packetId == Constants.Packets.OverseaLadderMatchBattleEnd then
        -- print("->>>UIBattlingPVPMgr:OnReceiveBattleEndPacketSuccessHandler_:", table.dump(checkTable(data)))
        if checkBool(self.isBattleOver) then return end
        self.isBattleOver = true
        data = checkTable(data)
        local matchResult = checkInt(data.matchResult)
        self.matchResultData = data
    end
end

