    Events.RemoveListener(Constants.EventNames.BattleRequireInput, self.eventRequireInput)
    Events.RemoveListener(Constants.EventNames.BattleOnNetworkDisconnected, self.eventOnNetworkDisconnected)
    Events.RemoveListener(Constants.EventNames.ReceivePacketSuccess, self.eventLadderCompetionBattleEnd)
