---StartInputLimitTimer
---出手时限
function UIBattlingPVPMgr:StartInputLimitTimer(CBCountDown, CBFinish, timeLimit)
    if UIBattleSettingMgr.showRemainTime then
        self:StopInputLimitTimer()
        self.timerStart = TimeZoneUtils.UtcSeconds
        if CBCountDown then
            self.callBackCD = CBCountDown
        end
        if CBFinish then
            self.callBackFinish = CBFinish
        end
        self.coInputLimitTimer = cs_coroutine.start(function()
            local serviceTimeNow = TimeZoneUtils.UtcSeconds
            while serviceTimeNow - self.timerStart <= timeLimit do
                serviceTimeNow = TimeZoneUtils.UtcSeconds
                local timeCost = timeLimit - (serviceTimeNow - self.timerStart)
                self.timeRemain = timeCost
                if self.callBackCD then
                    self.callBackCD(timeCost)
                end
                cs_coroutine.yield_return(timeCost > 2 and WaitForSeconds(1) or nil)
                if self.isBattleOver then
                    self.coInputLimitTimer = nil
                    return
                end
            end
            if self.callBackFinish then
                self.callBackFinish()
            end
            self.coInputLimitTimer = nil
        end)
    end
end

function UIBattlingPVPMgr:StopInputLimitTimer()
    if self.coInputLimitTimer then
        cs_coroutine.stop(self.coInputLimitTimer)
        self:CleanTimerCallBack()
        self.coInputLimitTimer = nil
        self.timerStart = 0
        self.timeRemain = nil
    end
end

function UIBattlingPVPMgr:SetInputLimitTimer(remainTime)
    self:StartInputLimitTimer(
            function(timeCost)
                if self.refPVPDialog then
                    self.refPVPDialog:SetTimerValue(timeCost)
                end
            end, 
            function()
                -- self:ActionOnMyPlayerInputFinish(Constants.InputFinishType.PVPTimerCallBack)
                -- Events.Broadcast(Constants.EventNames.BattleInputFinished, Constants.InputFinishType.PVPTimerCallBack)
                --Events.Broadcast(Constants.EventNames.UIBattlingCountDownFinish)
            end,
            remainTime
        )
end

