        if self.refPVPDialog then
            self.refPVPDialog:ActionOnInputFinished()
        end
    end)
end

function UIBattlingPVPMgr:BattleRequireInputFun(logicData)
    if not BattleInfo:IsUserCamp(logicData.camp) then
            -- print("->>>UIBattlingPVPMgr:BattleRequireInputFun", table.dump(logicData))
        self:UpdateEnemyActionPoint(logicData.actionPoint)
        if self.refPVPDialog then
            self.refPVPDialog:UpgradeSkillCardSequenceBGState()
        end
    end
    if UIBattleSettingMgr.showRemainTime
    and (UIBattleSettingMgr.UIType == UIBattleSettingMgr.EnumUIType.PVP
    or UIBattleSettingMgr.UIType == UIBattleSettingMgr.EnumUIType.PPVE) then
        self:ActionOnTurnStart()
        -- 重连的时候会传过来一个剩余时间
        local waitTime = isNull(logicData.remainTime) and (UIBattleSettingMgr.waitingSeconds - 1) or (logicData.remainTime - 1)
        self:SetInputLimitTimer(waitTime)  -- 减1s，保证比服务器时间短
    end
end

function UIBattlingPVPMgr:UpdateEnemyActionPoint(point)
    self.enemyActionPoint = point
end

